<?php
require_once 'database.php';
if($_SERVER['REQUEST_METHOD']==='POST'){ $sid=(int)$_POST['student_id'];$subject=trim($_POST['subject']);$marks=(float)$_POST['marks'];$s=$conn->prepare("INSERT INTO results(student_id,subject,marks) VALUES(?,?,?)");$s->bind_param("isd",$sid,$subject,$marks);$s->execute();header('Location:results.php');exit;}
$students=$conn->query("SELECT id,student_id,first_name,last_name FROM students ORDER BY first_name");$records=$conn->query("SELECT r.*,s.student_id,s.first_name,s.last_name FROM results r JOIN students s ON s.id=r.student_id ORDER BY r.id DESC");
?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Results</title><link rel="stylesheet" href="style.css"></head><body><div class="container"><header><h1>Results</h1></header><nav><a href="index.php">Students</a><a href="add_student.php">Add Student</a><a href="attendance.php">Attendance</a><a class="active" href="results.php">Results</a></nav><form class="form-card" method="post"><div class="form-grid"><label>Student<select name="student_id" required><?php while($s=$students->fetch_assoc()):?><option value="<?=$s['id']?>"><?=htmlspecialchars($s['student_id'].' - '.$s['first_name'].' '.$s['last_name'])?></option><?php endwhile;?></select></label><label>Subject<input name="subject" required></label><label>Marks<input type="number" name="marks" min="0" max="100" step="0.01" required></label></div><button class="button">Save Result</button></form><div class="table-wrap"><table><tr><th>Student</th><th>Subject</th><th>Marks</th></tr><?php while($r=$records->fetch_assoc()):?><tr><td><?=htmlspecialchars($r['student_id'].' - '.$r['first_name'].' '.$r['last_name'])?></td><td><?=htmlspecialchars($r['subject'])?></td><td><?=htmlspecialchars($r['marks'])?></td></tr><?php endwhile;?></table></div></div></body></html>